  "C# 12": "C# 12",
  "CATEGORY \u00b7 COLOUR \u00b7 THICKNESS \u00b7 WIDTH \u00d7 HEIGHT": "\u0627\u0644\u0641\u0626\u0629 \u00b7 \u0627\u0644\u0644\u0648\u0646 \u00b7 \u0627\u0644\u0633\u064f\u0645\u0643 \u00b7 \u0627\u0644\u0639\u0631\u0636 \u00d7 \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639",
  "CNC glass cutting export": "\u062a\u0635\u062f\u064a\u0631 \u0642\u0635 \u0627\u0644\u0632\u062c\u0627\u062c \u0628\u0627\u0644\u062a\u062d\u0643\u0645 \u0627\u0644\u0631\u0642\u0645\u064a",
  "CONSUMPTION, MOVEMENTS, ANALYSIS and REORDER LEVEL": "\u0627\u0644\u0627\u0633\u062a\u0647\u0644\u0627\u0643\u060c \u0648\u0627\u0644\u062d\u0631\u0643\u0627\u062a\u060c \u0648\u0627\u0644\u062a\u062d\u0644\u064a\u0644\u060c \u0648\u062d\u062f \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0637\u0644\u0628",
  "CSV, Excel, DXF and Bottero / Intermac / Lisec machine files": "CSV \u0648Excel \u0648DXF \u0648\u0645\u0644\u0641\u0627\u062a \u0622\u0644\u0627\u062a Bottero / Intermac / Lisec",
  "CUT TAG and Breakout indicators": "\u0648\u0633\u0648\u0645 \u0627\u0644\u0642\u0635 \u0648\u0645\u0624\u0634\u0631\u0627\u062a \u0627\u0644\u0641\u0635\u0644",
  "CUTTING COMPLEXITY: free guillotine \u2192 3-stage \u2192 Z/W trims": "\u062a\u0639\u0642\u064a\u062f \u0627\u0644\u0642\u0635: \u0645\u0642\u0635\u0651 \u062d\u0631\u0651 \u2190 3 \u0645\u0631\u0627\u062d\u0644 \u2190 \u062a\u0642\u0644\u064a\u0645\u0627\u062a Z/W",
