  "Can I run it against a rack that is nearly empty?": "\u0647\u0644 \u0623\u0633\u062a\u0637\u064a\u0639 \u062a\u0634\u063a\u064a\u0644\u0647 \u0639\u0644\u0649 \u0631\u0641\u0651 \u0634\u0628\u0647 \u0641\u0627\u0631\u063a\u061f",
  "Can I try it before buying?": "\u0647\u0644 \u0623\u0633\u062a\u0637\u064a\u0639 \u062a\u062c\u0631\u0628\u062a\u0647 \u0642\u0628\u0644 \u0627\u0644\u0634\u0631\u0627\u0621\u061f",
  "Can a company sponsor in exchange for a logo or a credit?": "\u0647\u0644 \u064a\u0645\u0643\u0646 \u0644\u0634\u0631\u0643\u0629 \u0623\u0646 \u062a\u0631\u0639\u0649 \u0645\u0642\u0627\u0628\u0644 \u0634\u0639\u0627\u0631 \u0623\u0648 \u0630\u0643\u0631\u061f",
  "Can read": "\u064a\u0645\u0643\u0646\u0647 \u0627\u0644\u0642\u0631\u0627\u0621\u0629",
  "Can several people work in the same data at once?": "\u0647\u0644 \u064a\u0645\u0643\u0646 \u0644\u0639\u062f\u0629 \u0623\u0634\u062e\u0627\u0635 \u0627\u0644\u0639\u0645\u0644 \u0639\u0644\u0649 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0646\u0641\u0633\u0647\u0627 \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0630\u0627\u062a\u0647\u061f",
  "Cannot": "\u0644\u0627 \u064a\u0645\u0643\u0646\u0647",
  "Capability groups": "\u0645\u062c\u0645\u0648\u0639\u0627\u062a \u0627\u0644\u0642\u062f\u0631\u0627\u062a",
