  "Card": "\u0628\u0637\u0627\u0642\u0629",
  "Card edge": "\u062d\u062f\u0651 \u0627\u0644\u0628\u0637\u0627\u0642\u0629",
  "Card tint": "\u062a\u062f\u0631\u0651\u062c \u0627\u0644\u0628\u0637\u0627\u0642\u0629",
