  "Carries forward": "\u064a\u064f\u0631\u062d\u064e\u0651\u0644",
  "Categories": "\u0627\u0644\u0641\u0626\u0627\u062a",
  "Category mix": "\u0645\u0632\u064a\u062c \u0627\u0644\u0641\u0626\u0627\u062a",
  "Ceramic frit": "\u0637\u0628\u0639\u0629 \u0633\u064a\u0631\u0627\u0645\u064a\u0643",
  "Ceramic frit 6 mm": "\u0637\u0628\u0639\u0629 \u0633\u064a\u0631\u0627\u0645\u064a\u0643 6 \u0645\u0645",
  "Change how this site looks while you use it. Every choice is saved, and every one maps to a real": "\u063a\u064a\u0651\u0631 \u0634\u0643\u0644 \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0642\u0639 \u0623\u062b\u0646\u0627\u0621 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647. \u0643\u0644 \u0627\u062e\u062a\u064a\u0627\u0631 \u064a\u064f\u062d\u0641\u064e\u0638\u060c \u0648\u0643\u0644 \u0627\u062e\u062a\u064a\u0627\u0631 \u064a\u0642\u0627\u0628\u0644",
  "Change language": "\u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0644\u063a\u0629",
  "Charge": "\u0627\u0644\u0631\u0633\u0645",
  "Charges, VAT 5% round-safe summary, attachments, stored P&L snapshot": "\u0627\u0644\u0631\u0633\u0648\u0645\u060c \u0648\u0645\u0644\u062e\u0651\u0635 \u0636\u0631\u064a\u0628\u0629 5% \u0627\u0644\u0645\u0623\u0645\u0648\u0646 \u0627\u0644\u062a\u0642\u0631\u064a\u0628\u060c \u0648\u0627\u0644\u0645\u0631\u0641\u0642\u0627\u062a\u060c \u0648\u0644\u0642\u0637\u0629 \u0627\u0644\u0623\u0631\u0628\u0627\u062d \u0648\u0627\u0644\u062e\u0633\u0627\u0626\u0631 \u0627\u0644\u0645\u062e\u0632\u064e\u0651\u0646\u0629",
