  "Checked against the job order": "\u0645\u0637\u0627\u0628\u064e\u0642 \u0645\u0642\u0627\u0628\u0644 \u0623\u0645\u0631 \u0627\u0644\u062a\u0634\u063a\u064a\u0644",
