  "Clear 12 mm": "\u0634\u0641\u0627\u0641 12 \u0645\u0645",
  "Clear 6 / 8 / 10 / 12 \u00b7 Tinted 6 / 8 \u00b7 Low-E 6 \u00b7 Frosted 5": "\u0634\u0641\u0627\u0641 6 / 8 / 10 / 12 \u00b7 \u0645\u0635\u0628\u0648\u063a 6 / 8 \u00b7 \u0645\u0646\u062e\u0641\u0636 \u0627\u0644\u0627\u0646\u0628\u0639\u0627\u062b\u064a\u0629 6 \u00b7 \u0645\u0635\u0646\u0641\u0631 5",
  "Clear 6 mm": "\u0634\u0641\u0627\u0641 6 \u0645\u0645",
  "Clear 6 mm 46 \u00b7 Clear 8 mm 18 \u00b7 Clear 10 mm 9 \u00b7 Clear 12 mm 4": "\u0634\u0641\u0627\u0641 6 \u0645\u0645 46 \u00b7 \u0634\u0641\u0627\u0641 8 \u0645\u0645 18 \u00b7 \u0634\u0641\u0627\u0641 10 \u0645\u0645 9 \u00b7 \u0634\u0641\u0627\u0641 12 \u0645\u0645 4",
