  "Clear Float": "\u0634\u0641\u0627\u0641 \u0639\u0627\u062f\u064a",
  "Clear Tempered \u2014 Main Facade": "\u0634\u0641\u0627\u0641 \u0645\u0642\u0633\u0651\u0649 \u2014 \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629",
  "Client Profile": "\u0645\u0644\u0641 \u0627\u0644\u0639\u0645\u064a\u0644",
  "Close": "\u0625\u063a\u0644\u0627\u0642",
  "Coating removal where a sealed unit or a bonded edge needs the surface taken back.": "\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0637\u0644\u0627\u0621 \u062d\u064a\u062b \u062a\u062d\u062a\u0627\u062c \u0648\u062d\u062f\u0629 \u0645\u062d\u0643\u0645\u0629 \u0623\u0648 \u062d\u0627\u0641\u0629 \u0645\u0644\u0635\u0648\u0642\u0629 \u0625\u0644\u0649 \u0643\u0634\u0641 \u0627\u0644\u0633\u0637\u062d.",
  "Code, documents, tests, this site.": "\u0627\u0644\u0643\u0648\u062f\u060c \u0648\u0627\u0644\u0645\u0633\u062a\u0646\u062f\u0627\u062a\u060c \u0648\u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0642\u0639.",
  "Collapsible navigation rail so a report can use the full width": "\u0634\u0631\u064a\u0637 \u062a\u0646\u0642\u0651\u0644 \u0642\u0627\u0628\u0644 \u0644\u0644\u0637\u064a \u0644\u064a\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0643\u0627\u0645\u0644",
  "Collections pulse": "\u0646\u0628\u0636 \u0627\u0644\u062a\u062d\u0635\u064a\u0644",
  "Collections pulse: customer balances, outstanding value and collection risk \u00b7 ageing brackets": "\u0646\u0628\u0636 \u0627\u0644\u062a\u062d\u0635\u064a\u0644: \u0623\u0631\u0635\u062f\u0629 \u0627\u0644\u0639\u0645\u0644\u0627\u0621\u060c \u0648\u0642\u064a\u0645\u0629 \u0627\u0644\u0645\u0633\u062a\u062d\u0642\u060c \u0648\u0645\u062e\u0627\u0637\u0631 \u0627\u0644\u062a\u062d\u0635\u064a\u0644 \u00b7 \u0641\u0626\u0627\u062a \u0627\u0644\u062a\u0642\u0627\u062f\u0645",
  "Columns are LM-based: QTY \u00b7 LM1 \u00b7 LM2 \u00b7 IN \u00b7 DONE \u00b7 BALANCE": "\u0627\u0644\u0623\u0639\u0645\u062f\u0629 \u0628\u0627\u0644\u0623\u0645\u062a\u0627\u0631 \u0627\u0644\u0637\u0648\u0644\u064a\u0629: \u0627\u0644\u0643\u0645\u064a\u0629 \u00b7 LM1 \u00b7 LM2 \u00b7 \u0627\u0644\u0648\u0627\u0631\u062f \u00b7 \u0627\u0644\u0645\u0646\u062c\u0632 \u00b7 \u0627\u0644\u0631\u0635\u064a\u062f",
  "Columns are LM-based: QTY \u00b7 LM1 \u00b7 LM2 \u00b7 IN \u00b7 DONE \u00b7 BALANCE \u2014 no pricing and no SQM noise": "\u0627\u0644\u0623\u0639\u0645\u062f\u0629 \u0628\u0627\u0644\u0623\u0645\u062a\u0627\u0631 \u0627\u0644\u0637\u0648\u0644\u064a\u0629: \u0627\u0644\u0643\u0645\u064a\u0629 \u00b7 LM1 \u00b7 LM2 \u00b7 \u0627\u0644\u0648\u0627\u0631\u062f \u00b7 \u0627\u0644\u0645\u0646\u062c\u0632 \u00b7 \u0627\u0644\u0631\u0635\u064a\u062f \u2014 \u0628\u0644\u0627 \u062a\u0633\u0639\u064a\u0631 \u0648\u0628\u0644\u0627 \u0636\u062c\u064a\u062c \u0645\u00b2",
  "Columns: ST \u00b7 JOB \u00b7 PI \u00b7 CUSTOMER \u00b7 SALESMAN \u00b7 SPEC \u00b7 SR \u00b7 REF \u00b7 BUILD \u00b7 W1 \u00b7 H1 \u00b7 W2 \u00b7 H2 \u00b7 QTY": "\u0627\u0644\u0623\u0639\u0645\u062f\u0629: ST \u00b7 \u0627\u0644\u0639\u0645\u0644 \u00b7 PI \u00b7 \u0627\u0644\u0639\u0645\u064a\u0644 \u00b7 \u0627\u0644\u0645\u0646\u062f\u0648\u0628 \u00b7 \u0627\u0644\u0645\u0648\u0627\u0635\u0641\u0629 \u00b7 \u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u062a\u0633\u0644\u0633\u0644\u064a \u00b7 \u0627\u0644\u0645\u0631\u062c\u0639 \u00b7 \u0627\u0644\u062a\u0631\u0643\u064a\u0628\u0629 \u00b7 \u06391 \u00b7 \u06271 \u00b7 \u06392 \u00b7 \u06272 \u00b7 \u0627\u0644\u0643\u0645\u064a\u0629",
  "Columns: job, spec, piece, process, previous stage, status, qty, progress, QC, operator": "\u0627\u0644\u0623\u0639\u0645\u062f\u0629: \u0627\u0644\u0639\u0645\u0644\u060c \u0648\u0627\u0644\u0645\u0648\u0627\u0635\u0641\u0629\u060c \u0648\u0627\u0644\u0642\u0637\u0639\u0629\u060c \u0648\u0627\u0644\u0639\u0645\u0644\u064a\u0629\u060c \u0648\u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0633\u0627\u0628\u0642\u0629\u060c \u0648\u0627\u0644\u062d\u0627\u0644\u0629\u060c \u0648\u0627\u0644\u0643\u0645\u064a\u0629\u060c \u0648\u0627\u0644\u062a\u0642\u062f\u0651\u0645\u060c \u0648\u0641\u062d\u0635 \u0627\u0644\u062c\u0648\u062f\u0629\u060c \u0648\u0627\u0644\u0645\u0634\u063a\u0651\u0644",
  "Combined PDF including signed PI and signed delivery notes": "\u0645\u0644\u0641 PDF \u0645\u062f\u0645\u062c \u064a\u0634\u0645\u0644 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 \u0627\u0644\u0623\u0648\u0644\u064a\u0629 \u0627\u0644\u0645\u0648\u0642\u064e\u0651\u0639\u0629 \u0648\u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u0627\u0644\u0645\u0648\u0642\u064e\u0651\u0639\u0629",
  "Combined signed-document PDF support": "\u062f\u0639\u0645 PDF \u0644\u0644\u0645\u0633\u062a\u0646\u062f\u0627\u062a \u0627\u0644\u0645\u0648\u0642\u064e\u0651\u0639\u0629 \u0627\u0644\u0645\u062f\u0645\u062c\u0629",
