  "Default cutting allowances per glass thickness bucket": "\u0647\u0648\u0627\u0645\u0634 \u0627\u0644\u0642\u0635 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629 \u0628\u062d\u0633\u0628 \u0641\u0626\u0629 \u0633\u064f\u0645\u0643 \u0627\u0644\u0632\u062c\u0627\u062c",
  "Deliver part of an order": "\u0633\u0644\u0651\u0645 \u062c\u0632\u0621\u064b\u0627 \u0645\u0646 \u0627\u0644\u0637\u0644\u0628",
  "Delivered": "\u0627\u0644\u0645\u064f\u0633\u0644\u064e\u0651\u0645",
  "Delivered 40 pieces \u00b7 balance 5 pieces \u00b7 DN-1841": "\u0633\u064f\u0644\u0650\u0651\u0645\u062a 40 \u0642\u0637\u0639\u0629 \u00b7 \u0627\u0644\u0631\u0635\u064a\u062f 5 \u0642\u0637\u0639 \u00b7 DN-1841",
  "Delivered and outstanding quantity per specification group.": "\u0627\u0644\u0643\u0645\u064a\u0629 \u0627\u0644\u0645\u0633\u0644\u064e\u0651\u0645\u0629 \u0648\u0627\u0644\u0645\u062a\u0628\u0642\u064a\u0629 \u0644\u0643\u0644 \u0645\u062c\u0645\u0648\u0639\u0629 \u0645\u0648\u0627\u0635\u0641\u0627\u062a.",
  "Delivered quantities \u2192 the tax invoice": "\u0627\u0644\u0643\u0645\u064a\u0627\u062a \u0627\u0644\u0645\u0633\u0644\u064e\u0651\u0645\u0629 \u2190 \u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 \u0627\u0644\u0636\u0631\u064a\u0628\u064a\u0629",
  "Deliveries do not arrive in one piece": "\u0627\u0644\u062a\u0633\u0644\u064a\u0645\u0627\u062a \u0644\u0627 \u062a\u0635\u0644 \u062f\u0641\u0639\u0629 \u0648\u0627\u062d\u062f\u0629",
  "Deliveries \u2014 dispatch and balance": "\u0627\u0644\u062a\u0633\u0644\u064a\u0645\u0627\u062a \u2014 \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0648\u0627\u0644\u0631\u0635\u064a\u062f",
  "Delivery Note": "\u0625\u0634\u0639\u0627\u0631 \u062a\u0633\u0644\u064a\u0645",
