  "Desktop software \u00b7 v{version} \u00b7 No account required": "\u0628\u0631\u0646\u0627\u0645\u062c \u0633\u0637\u062d \u0645\u0643\u062a\u0628 \u00b7 v{version} \u00b7 \u0628\u0644\u0627 \u062d\u0627\u062c\u0629 \u0625\u0644\u0649 \u062d\u0633\u0627\u0628",
  "Desktop, by design": "\u0633\u0637\u062d \u0627\u0644\u0645\u0643\u062a\u0628\u060c \u0628\u062d\u0643\u0645 \u0627\u0644\u062a\u0635\u0645\u064a\u0645",
  "Detail grid across all units of the job": "\u062c\u062f\u0648\u0644 \u062a\u0641\u0635\u064a\u0644\u064a \u0639\u0628\u0631 \u0643\u0644 \u0648\u062d\u062f\u0627\u062a \u0627\u0644\u0639\u0645\u0644",
  "Detail grid with the job's outer and inner cut lists": "\u062c\u062f\u0648\u0644 \u062a\u0641\u0635\u064a\u0644\u064a \u0628\u0642\u0627\u0626\u0645\u062a\u064a \u0627\u0644\u0642\u0635 \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0629 \u0648\u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0629 \u0644\u0644\u0639\u0645\u0644",
