  "Scope-of-supply capture with the customer and project cards": "\u0627\u0644\u062a\u0642\u0627\u0637 \u0646\u0637\u0627\u0642 \u0627\u0644\u062a\u0648\u0631\u064a\u062f \u0628\u0628\u0637\u0627\u0642\u062a\u064a \u0627\u0644\u0639\u0645\u064a\u0644 \u0648\u0627\u0644\u0645\u0634\u0631\u0648\u0639",
  "Scrap": "\u0627\u0644\u0647\u062f\u0631",
  "Screen Record": "\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0634\u0627\u0634\u0629",
