  "Spandrel, screen": "\u062a\u0643\u0633\u064a\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0648\u0634\u0628\u0643",
  "Spec group": "\u0645\u062c\u0645\u0648\u0639\u0629 \u0627\u0644\u0645\u0648\u0627\u0635\u0641\u0627\u062a",
