  "Specification {number}": "\u0627\u0644\u0645\u0648\u0627\u0635\u0641\u0629 {number}",
  "Specifications library": "\u0645\u0643\u062a\u0628\u0629 \u0627\u0644\u0645\u0648\u0627\u0635\u0641\u0627\u062a",
